import java.nio.file.Paths;
public class T {
  public static void main(String[] a) throws Exception {
    try {
      Paths.get("foo\u0000bar");
      System.out.println("no exception");
    } catch (Exception e) {
      System.out.println("threw: " + e.getClass());
    }
    try {
      Class.forName("java.lang.Runnable").getConstructor();
      System.out.println("no exception for getConstructor");
    } catch (Exception e) {
      System.out.println("threw2: " + e.getClass());
    }
  }
}
EOF
javac -d $TMPDIR $TMPDIR/T.java && java -cp $TMPDIR T
